}

.nav-link:hover {
    color: var(--accent);
}

.header-actions {
    display: flex;
    gap: var(--spacing-md);
}

/* ===========================
   Hero Section
   =========================== */

.hero {
    background: linear-gradient(135deg, rgba(212, 175, 55, 0.1), rgba(0, 0, 0, 0.3));
