    font-weight: 700;
    margin-bottom: var(--spacing-md);
    letter-spacing: -0.5px;
}

.hero-subtitle {
    font-size: var(--font-size-lg);
    color: var(--text-secondary);
    margin-bottom: var(--spacing-lg);
}

/* ===========================
   Section Styling
   =========================== */

.section-title {
    font-size: var(--font-size-3xl);
    font-weight: 700;
    margin-bottom: var(--spacing-xl);
    text-align: center;
    letter-spacing: -0.5px;
}

main > section {
