 * Shopping Home Page - Interactivity Script
 * Handles buttons, forms, and enhanced user interactions
 */

document.addEventListener('DOMContentLoaded', () => {
    initializeButtons();
    initializeNewsletterForm();
    initializeScrollAnimations();
});

/**
 * Initialize button interactions
 */
function initializeButtons() {
    const cartButtons = document.querySelectorAll('.btn-secondary');
    const shopButtons = document.querySelectorAll('.btn-accent');
    const ctaButton = document.querySelector('.hero .btn-primary');

    cartButtons.forEach(btn => {
        btn.addEventListener('click', handleAddToCart);
    });

    shopButtons.forEach(btn => {
        btn.addEventListener('click', handleShopNow);
    });

    if (ctaButton) {
        ctaButton.addEventListener('click', handleExploreCollection);
    }
}

/**
 * Handle add to cart button click
 */
function handleAddToCart(e) {
    const button = e.target.closest('button');
    const productCard = button.closest('.product-card');
    const productName = productCard.querySelector('.product-name').textContent;

    showToast(`Added "${productName}" to cart`);

    // Visual feedback
    const originalText = button.textContent;
    button.textContent = '✓ Added';
    button.style.opacity = '0.7';

    setTimeout(() => {
        button.textContent = originalText;
        button.style.opacity = '1';
    }, 2000);
}

/**
 * Handle shop now button click
 */
function handleShopNow(e) {
    const button = e.target.closest('button');
    const dealCard = button.closest('.deal-card');
    const dealTitle = dealCard.querySelector('.deal-title').textContent;

    showToast(`Exploring ${dealTitle}...`);
}

/**
 * Handle explore collection button click
 */
function handleExploreCollection(e) {
    const productsSection = document.getElementById('products');
    productsSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

/**
 * Initialize newsletter form submission
 */
function initializeNewsletterForm() {
    const form = document.querySelector('.newsletter-form');

    if (!form) return;

    form.addEventListener('submit', (e) => {
        e.preventDefault();

        const emailInput = form.querySelector('.input-field');
        const email = emailInput.value.trim();

        if (!email) {
            showToast('Please enter your email address', 'error');
            return;
        }

        if (!isValidEmail(email)) {
            showToast('Please enter a valid email address', 'error');
            return;
        }

        // Show success message
        showToast('✓ Successfully subscribed!');

        // Reset form
        emailInput.value = '';
        emailInput.focus();
    });
}

/**
 * Validate email format
 */
function isValidEmail(email) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
}

/**
 * Initialize scroll animations for elements
 */
function initializeScrollAnimations() {
    const observerOptions = {
        threshold: 0.1,
        rootMargin: '0px 0px -100px 0px'
    };

    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
