/* ===========================
   Accessibility Utilities
   =========================== */

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background-color: var(--accent);
    color: var(--bg-primary);
    padding: var(--spacing-sm);
    text-decoration: none;
    border-radius: var(--radius-md);
    font-weight: 600;
    z-index: 9999;
}

.skip-link:focus {
    top: var(--spacing-md);
