 */
function handleShopNow(e) {
    const button = e.target.closest('button');
    const dealCard = button.closest('.deal-card');
    const dealTitle = dealCard.querySelector('.deal-title').textContent;

    showToast(`Exploring ${dealTitle}...`);
}

/**
 * Handle explore collection button click
 */
function handleExploreCollection(e) {
    const productsSection = document.getElementById('products');
    productsSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

/**
 * Initialize newsletter form submission
 */
function initializeNewsletterForm() {
    const form = document.querySelector('.newsletter-form');

    if (!form) return;

    form.addEventListener('submit', (e) => {
        e.preventDefault();

        const emailInput = form.querySelector('.input-field');
        const email = emailInput.value.trim();

        if (!email) {
            showToast('Please enter your email address', 'error');
            return;
        }

        if (!isValidEmail(email)) {
            showToast('Please enter a valid email address', 'error');
            return;
        }

        // Show success message
        showToast('✓ Successfully subscribed!');

        // Reset form
        emailInput.value = '';
        emailInput.focus();
    });
}

